mapper.select:
select id, title, sub_title as subTitle, kind, is_enabled as isEnabled, points, price, image, stock, available_stock as availableStock, frozen_stock as frozenStock, sale_volume as saleVolume, version, create_time as createTime, update_time as updateTime, remark from points_gift
and title like concat('%', #{title}, '%') and kind = #{kind} and is_enabled = #{isEnabled}
order by create_time desc, id desc

mapper.update:
update points_gift
set title = #{title}, sub_title = #{subTitle}, kind = #{kind}, is_enabled = #{isEnabled},
    points = #{points}, price = #{price}, image = #{image}, update_by = #{updateBy},
    update_time = now(), remark = #{remark}
where id = #{id}

mapper.select:
select ou.id as userId, ou.username, ou.phone_number as phoneNumber, ifnull(pa.available_points, 0) as availablePoints, ifnull(pa.points, 0) as points, ifnull(pa.frozen_points, 0) as frozenPoints, ifnull(pa.version, 0) as version, coalesce(pa.create_time, ou.create_time) as createTime from order_user ou left join points_account pa on pa.user_id = ou.id
and ou.username like concat('%', #{username}, '%') and ou.phone_number like concat('%', #{phoneNumber}, '%') and ifnull(pa.available_points, 0) >= #{minAvailablePoints} and ifnull(pa.available_points, 0) <= #{maxAvailablePoints}
order by ou.create_time desc, ou.id desc

mapper.update:
update points_account
set points = #{points}, available_points = #{availablePoints}, version = version + 1, update_time = now()
where user_id = #{userId}

mapper.select:
select pf.id, pf.flow_no as flowNo, pf.user_id as userId, pf.username_snapshot as username, pf.phone_snapshot as phoneNumber, pf.before_points as beforePoints, pf.change_points as changePoints, pf.after_points as afterPoints, pf.transaction_no as transactionNo, pf.create_time as createTime, pf.remark from points_flow pf
and pf.flow_no = #{flowNo} and pf.username_snapshot like concat('%', #{username}, '%') and pf.phone_snapshot like concat('%', #{phoneNumber}, '%') and pf.change_points >= #{minPoints} and pf.change_points <= #{maxPoints}
order by pf.create_time desc, pf.id desc

select pgo.id, pgo.order_no as orderNo, pgo.user_id as userId,
       pgo.username_snapshot as username,
       pgo.gift_id as giftId, pgo.gift_image as giftImage, pgo.gift_title as giftTitle,
       pgo.points, pgo.status, pgo.consignee, pgo.telephone,
       pgo.delivery_address as deliveryAddress, pgo.version,
       pgo.create_time as createTime, pgo.update_time as updateTime, pgo.remark
from points_gift_order pgo

    and pgo.order_no = #{orderNo}
    and pgo.username_snapshot like concat('%', #{username}, '%')
    and pgo.gift_title like concat('%', #{giftTitle}, '%')
    and pgo.status = #{status}
    and pgo.points >= #{minPoints}
    and pgo.points <= #{maxPoints}
    and pgo.create_time >= #{startTime}
    and pgo.create_time <= #{endTime}

order by pgo.create_time desc, pgo.id desc

select id, title, sub_title as subTitle, is_enabled as isEnabled, sort_order as sortOrder,
       image, no_winning_tips as noWinningTips, rule_content as ruleContent, description,
       create_time as createTime, update_time as updateTime, remark
from activity_info

    and title like concat('%', #{title}, '%')
    and is_enabled = #{isEnabled}
    and create_time >= #{startTime}
    and create_time <= #{endTime}

order by sort_order asc, create_time desc, id desc

mapper.update:
update activity_info set title=#{title}, sub_title=#{subTitle}, is_enabled=#{isEnabled},
    sort_order=#{sortOrder}, image=#{image}, no_winning_tips=#{noWinningTips},
    rule_content=#{ruleContent}, description=#{description}, update_by=#{updateBy},
    update_time=now(), remark=#{remark}
where id=#{id}

mapper.select:
select ap.id, ap.activity_id as activityId, ai.title as activityTitle, ap.probability,
       ap.title, ap.sub_title as subTitle, ap.kind, ap.price, ap.is_enabled as isEnabled,
       ap.sort_order as sortOrder, ap.image, ap.create_time as createTime,
       ap.update_time as updateTime, ap.remark
from activity_prize ap join activity_info ai on ai.id=ap.activity_id

    and ap.activity_id=#{activityId}
    and ap.title like concat('%',#{title},'%')
    and ap.kind=#{kind}
    and ap.is_enabled=#{isEnabled}

order by ap.activity_id, ap.sort_order, ap.id

mapper.update:
update activity_prize set activity_id=#{activityId}, probability=#{probability}, title=#{title},
    sub_title=#{subTitle}, kind=#{kind}, price=#{price}, is_enabled=#{isEnabled},
    sort_order=#{sortOrder}, image=#{image}, update_by=#{updateBy}, update_time=now(), remark=#{remark}
where id=#{id}

mapper.select:
select ou.id as userId, ou.username, ou.phone_number as phoneNumber, ifnull(aa.available_times,0) as availableTimes, ifnull(aa.used_times,0) as usedTimes, ifnull(aa.version,0) as version, coalesce(aa.create_time,ou.create_time) as createTime from order_user ou left join activity_account aa on aa.user_id=ou.id
and ou.username like concat('%',#{username},'%') and ou.phone_number like concat('%',#{phoneNumber},'%') and ifnull(aa.available_times,0)>=#{minAvailableTimes} and ifnull(aa.available_times,0)<=#{maxAvailableTimes}
order by ou.create_time desc, ou.id desc

select aap.id,aap.user_id as userId,aap.activity_id as activityId,ai.title as activityTitle,
       aap.prize_id as prizeId,ap.title as prizeTitle,ap.image as prizeImage,ap.kind as prizeKind,
       ap.price as prizePrice,aap.sort_order as sortOrder,aap.is_winning as isWinning,
       aap.create_time as createTime,aap.remark
from activity_account_prize aap
join activity_info ai on ai.id=aap.activity_id
left join activity_prize ap on ap.id=aap.prize_id
where aap.user_id=#{userId}
and aap.activity_id=#{params.activityId}
and aap.sort_order=#{params.sortOrder}
and aap.is_winning=#{params.isWinning}
order by aap.sort_order,aap.id

select id,user_id as userId,activity_id as activityId,prize_id as prizeId,
       sort_order as sortOrder,is_winning as isWinning,create_time as createTime,remark
from activity_account_prize where id=#{id}

mapper.update:
update activity_account_prize set activity_id=#{activityId},prize_id=#{prizeId},
    sort_order=#{sortOrder},is_winning=#{isWinning},update_time=now(),remark=#{remark}
where id=#{id} and user_id=#{userId}

mapper.select:
select ap.id,ap.activity_id as activityId,ap.activity_title as activityTitle, ap.user_id as userId,ap.username_snapshot as username, ap.phone_snapshot as phoneNumber,ap.is_winning as isWinning, ap.prize_id as prizeId,ap.prize_image as prizeImage,ap.prize_title as prizeTitle, ap.prize_kind as prizeKind,ap.prize_price as prizePrice,ap.is_hidden as isHidden, ap.is_verified as isVerified,ap.create_time as createTime,ap.remark from activity_partner ap
and ap.activity_id=#{activityId} and ap.username_snapshot like concat('%',#{username},'%') and ap.phone_snapshot like concat('%',#{phoneNumber},'%') and ap.is_winning=#{isWinning} and ap.is_hidden=#{isHidden} and ap.is_verified=#{isVerified}
order by ap.create_time desc,ap.id desc
